if(EditorApplication.isPlaying)throw new System.Exception("Edit only");string D="ArtSource/Pipeline/Review/BriarwickWoodland03";var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();string Path(Transform t){return t.parent==null?t.name:Path(t.parent)+"/"+t.name;}var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var queues=all.GroupBy(t=>Path(t)).ToDictionary(g=>g.Key,g=>new System.Collections.Generic.Queue<Transform>(g));var old=Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText(D+"/SceneBefore.json"));var unexpected=new System.Collections.Generic.List<string>();int allowedMaterialChanges=0;foreach(var e in old){string p=(string)e["path"];if(!queues.ContainsKey(p)){unexpected.Add("Missing "+p);continue;}var t=queues[p].Dequeue();bool allowedActive=p=="Woodland01 - Mini Nature limited review/Woodland01_Remainder_Canopy"||p=="Woodland01 - Mini Nature limited review/Woodland01_Remainder_Trunks";if(t.gameObject.activeSelf!=(bool)e["active"]&&!allowedActive)unexpected.Add("Active "+p);foreach(var c in e["components"]){var comp=t.GetComponents<Component>().FirstOrDefault(x=>x!=null&&x.GetType().FullName==(string)c["type"]);if(comp==null){unexpected.Add("Missing component "+p);continue;}string json=EditorJsonUtility.ToJson(comp);if(json==(string)c["json"])continue;bool allowed=comp is MeshRenderer&&p.StartsWith("Woodland01 - Mini Nature limited review/BW_Woodland01_Tree");if(allowed){var a=Newtonsoft.Json.Linq.JObject.Parse(json);var b=Newtonsoft.Json.Linq.JObject.Parse((string)c["json"]);((Newtonsoft.Json.Linq.JObject)a.Properties().First().Value).Remove("m_Materials");((Newtonsoft.Json.Linq.JObject)b.Properties().First().Value).Remove("m_Materials");if(Newtonsoft.Json.Linq.JToken.DeepEquals(a,b)){allowedMaterialChanges++;continue;}}unexpected.Add(p+" "+comp.GetType().Name);}}
var checks=new System.Collections.Generic.List<object>();foreach(string suffix in new[]{"Canopy","Trunks"}){var before=all.First(t=>t.name=="Woodland01_Remainder_"+suffix).GetComponent<MeshFilter>().sharedMesh;var remain=GameObject.Find("Woodland03_Remainder_"+suffix).GetComponent<MeshFilter>().sharedMesh;var selected=all.First(t=>t.name=="Woodland03_Selected_"+suffix).GetComponent<MeshFilter>().sharedMesh;checks.Add(new{suffix,verticesPreserved=before.vertices.SequenceEqual(remain.vertices)&&before.vertices.SequenceEqual(selected.vertices),triangleIndicesPreserved=before.triangles.OrderBy(i=>i).SequenceEqual(remain.triangles.Concat(selected.triangles).OrderBy(i=>i)),remainingProxyTrees=remain.triangles.Length/27,selectedProxyTrees=selected.triangles.Length/27,selectedInactive=!all.First(t=>t.name=="Woodland03_Selected_"+suffix).gameObject.activeInHierarchy});}
var result=new{preexistingObjects=old.Count,allowedSceneLeafMaterialOverrides=allowedMaterialChanges,unexpectedChanges=unexpected,proxyChecks=checks};System.IO.File.WriteAllText(D+"/ScenePreservation.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;
